export function ShareDialog({list,state,actions,onClose}:{list:AppRecord;state:Bootstrap;actions:Actions;onClose:()=>void}){const api=accountApi(state.user.userId);const [email,setEmail]=useState('');const [role,setRole]=useState('edit');const [invite,setInvite]=useState('');const [error,setError]=useState('');const [pendingInvites,setPendingInvites]=useState<any[]>([]);const loadInvites=async()=>{if(list.ownerId!==state.user.userId)return;try{const data=await api('/api/collaboration?listId='+encodeURIComponent(list.id));setPendingInvites(data.invitations||[])}catch{}};useEffect(()=>{loadInvites()},[list.id]);return <Modal title={'协作 · '+list.data.title} onClose={onClose}><p className="form-help">共享清单通过指定邮箱邀请，权限在服务端检查。此站点目前为私人访问；邀请他人前，需要先由站点所有者调整站点访问设置。创建链接不会发送邮件。</p><div className="members"><div><span className="avatar tiny">我</span><strong>{state.user.email}</strong><small>{list.ownerId===state.user.userId?'所有者':'当前账号'}</small></div>{state.members.filter(m=>m.listId===list.id&&m.userId!==state.user.userId).map(m=><div key={m.userId}><Users size={16}/><span>{m.email}</span>{list.ownerId===state.user.userId?<><select value={m.role} onChange={async e=>{try{await api('/api/collaboration',{operation:'role',listId:list.id,userId:m.userId,role:e.target.value});actions.refresh()}catch(e){setError((e as Error).message)}}}><option value="edit">可编辑</option><option value="comment">可评论</option><option value="read">仅查看</option></select><button className="icon-button" title="移除成员" onClick={async()=>{try{await api('/api/collaboration',{operation:'remove',listId:list.id,userId:m.userId});actions.refresh()}catch(e){setError((e as Error).message)}}}><X size={15}/></button></>:<small>{m.userId===list.ownerId?'所有者':m.role}</small>}</div>)}</div>{list.ownerId===state.user.userId&&<><label>邀请邮箱<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label><label>权限<select value={role} onChange={e=>setRole(e.target.value)}><option value="edit">可编辑任务</option><option value="comment">可查看与评论</option><option value="read">仅查看</option></select></label><button className="primary" disabled={!email.includes('@')} onClick={async()=>{try{const result=await api('/api/collaboration',{operation:'invite',listId:list.id,email,role});setInvite(result.url);setError('');loadInvites()}catch(e){setError((e as Error).message)}}}>生成 7 天有效的邀请链接</button></>}{list.ownerId!==state.user.userId&&<button className="subtle-button danger" onClick={async()=>{if(!confirm('离开此清单后将无法查看其任务，重新加入需要邀请。'))return;try{await api('/api/collaboration',{operation:'leave',listId:list.id});await actions.refresh();onClose()}catch(e){setError((e as Error).message)}}}>离开共享清单</button>}{pendingInvites.some(i=>!i.accepted_by)&&<div className="pending-invites"><h3>待接受邀请</h3>{pendingInvites.filter(i=>!i.accepted_by).map(i=><div key={i.id}><span>{i.email}<small>{i.expires_at<new Date().toISOString()?'已过期':new Date(i.expires_at).toLocaleDateString('zh-CN')+' 到期'} · {i.role}</small></span><button className="subtle-button danger" onClick={async()=>{try{await api('/api/collaboration',{operation:'revoke',listId:list.id,invitationId:i.id});loadInvites()}catch(e){setError((e as Error).message)}}}>撤销</button></div>)}</div>}{invite&&<div className="invite-link"><input readOnly value={invite}/><button onClick={()=>navigator.clipboard.writeText(invite).then(()=>actions.notify('邀请链接已复制'))}>复制</button></div>}<ListTransfer list={list} state={state} onRefresh={actions.refresh}/>{error&&<div className="inline-error">{error}</div>}</Modal>}
export function SettingsDialog({state,actions,onClose,settingsRecord}:{state:Bootstrap;actions:Actions;onClose:()=>void;settingsRecord?:AppRecord}){const[importFormat,setImportFormat]=useState('auto');const api=accountApi(state.user.userId);const [tab,setTab]=useState('appearance');const preferencesForm=useSettingsPreferences(state.user.userId,settingsRecord,actions);const prefs=preferencesForm.prefs;const canonicalPrefs=settingsRecord?.data||{};const [error,setError]=useState('');const [importing,setImporting]=useState(false);const importRef=useRef<HTMLInputElement>(null);const importOperation=useRef<{fingerprint:string;id:string}|null>(null);const importKey='qingdan:pending-import:'+state.user.userId;useEffect(()=>{try{const pending=JSON.parse(draftStore.getItem(importKey)||'null');if(pending&&typeof pending.fingerprint==='string'&&typeof pending.id==='string')importOperation.current=pending}catch{}},[]);const setPref=preferencesForm.setPref;
 const exportBackup=()=>download('青单备份-'+localDate()+'.json',JSON.stringify({format:'qingdan',version:1,exportedAt:new Date().toISOString(),records:state.records.filter(r=>r.ownerId===state.user.userId),history:state.history.filter(h=>state.records.some(r=>r.id===h.recordId&&r.ownerId===state.user.userId)),attachments:state.attachments.filter(a=>state.records.some(r=>r.id===a.recordId&&r.ownerId===state.user.userId)).map(a=>({...a,downloadUrl:location.origin+'/api/attachments?id='+a.id}))},null,2));
 const exportICS=()=>{const events=state.records.filter(r=>r.kind==='task'&&!r.deleted&&(r.data.dueDate||r.data.startDate)).map(r=>{const d=r.data;const zone=d.timezone||d.recurrence?.start.timeZone||canonicalPrefs.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone;const start=d.startInstant?{...instantToWallTime(d.startInstant,'UTC'),timeZone:undefined,utc:true}:{date:d.startDate||d.dueDate!,time:d.startTime||d.dueTime||undefined,...(d.startTime||d.dueTime?{timeZone:zone}:{})};const end=d.endInstant?{...instantToWallTime(d.endInstant,'UTC'),timeZone:undefined,utc:true}:d.startDate&&d.dueDate?{date:d.dueTime?d.dueDate!:addDays(d.dueDate!,1),time:d.dueTime||undefined,...(d.dueTime?{timeZone:zone}:{})}:undefined;return {uid:r.id+'@qingdan',title:d.title||'',description:d.description||'',start,end,categories:d.tags||[]}});const result=buildICS(events);download('青单日历-'+localDate()+'.ics',result.text,'text/calendar');if(result.warnings.length)actions.notify('导出含 '+result.warnings.length+' 项格式提示');};
 const exportCSV=()=>{const tasks=state.records.filter(r=>r.kind==='task'&&!r.deleted&&r.ownerId===state.user.userId).map(r=>({id:r.id,title:r.data.title||'',description:r.data.description||'',priority:(r.data.priority||0) as 0|1|2|3,tags:r.data.tags||[],list:state.records.find(l=>l.id===r.data.listId)?.data.title||'',section:r.data.section||'',parentId:r.data.parentId||undefined,dueDate:r.data.dueDate||undefined,dueTime:r.data.dueTime||undefined,timeZone:r.data.timezone||r.data.recurrence?.start.timeZone||canonicalPrefs.timezone,startDate:r.data.startDate||undefined,startTime:r.data.startTime||undefined,startInstant:r.data.startInstant||undefined,endInstant:r.data.endInstant||undefined,status:r.data.status||'open' as const,duration:r.data.duration}));download('青单任务-'+localDate()+'.csv',exportTaskCSV(tasks,{spreadsheetSafe:true}),'text/csv;charset=utf-8');};
 const importFile=async(file:File)=>{setImporting(true);setError('');try{if(file.size>5*1024*1024)throw new Error('文件最大5MB');const text=await file.text();const fingerprint=importFormat+'|'+file.name+'|'+file.size+'|'+file.lastModified; if(importOperation.current?.fingerprint!==fingerprint)importOperation.current={fingerprint,id:uid()};const operationId=importOperation.current.id;draftStore.setItem(importKey,JSON.stringify(importOperation.current));let result:any;if(importFormat==='graph-todo'){result=await api('/api/import-file',{format:'graph-todo',text,timeZone:canonicalPrefs.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone,listName:file.name.replace(/\.[^.]+$/,'').slice(0,100)});}else if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(text);if(data.format!=='qingdan'||data.version!==1||!Array.isArray(data.records))throw new Error('JSON需要青单v1备份。');result=await api('/api/import',{...data,operationId});}else{const format=file.name.toLowerCase().endsWith('.ics')?'ics':/TYPE.*CONTENT/i.test(text.split(/\r?\n/)[0])?'todoist':'csv';result=await api('/api/import-file',{operationId,format,text,timeZone:canonicalPrefs.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone,listName:file.name.replace(/\.[^.]+$/,'').slice(0,100)});}importOperation.current=null;draftStore.removeItem(importKey);await actions.refresh();actions.notify(`导入完成，共 ${result.count} 条记录。`);if(result.warnings?.length||result.notices?.length)setError('导入已完成；'+[...(result.notices||[]),...(result.warnings||[]).slice(0,8).map((w:any)=>w.message)].join('；'));}catch(e){setError((e as Error).message)}finally{setImporting(false)}};
 return <Modal title="设置" onClose={onClose} wide><div className="settings-layout"><nav>{[{id:'appearance',label:'外观与偏好'},{id:'account',label:'账号与同步'},...(state.user.mode==='accounts'&&state.user.role==='admin'?[{id:'users',label:'账号管理'}]:[]),{id:'notifications',label:'提醒与专注'},{id:'data',label:'导入与导出'},{id:'shortcuts',label:'快捷键'},{id:'about',label:'能力与边界'}].map(t=><button className={tab===t.id?'active':''} key={t.id} onClick={()=>setTab(t.id)}>{t.label}</button>)}</nav><section className="settings-content">{tab==='appearance'&&<><h3>外观</h3><label>主题<select value={prefs.theme||'light'} onChange={e=>setPref({theme:e.target.value as any})}><option value="light">浅色</option><option value="dark">深色</option><option value="system">跟随系统</option></select></label><label>一周开始于<select value={prefs.weekStart??1} onChange={e=>setPref({weekStart:Number(e.target.value)})}><option value={1}>星期一</option><option value={0}>星期日</option></select></label><label>日期时区<input aria-label="日期时区" value={prefs.timezone} onChange={e=>preferencesForm.change({timezone:e.target.value})} onBlur={()=>preferencesForm.saveField('timezone')}/></label><p className="form-help">日期按当地日历保存，避免全天任务被 UTC 偏移。定时任务按所选时区转换为实际时间，DST间隙选择兼容策略。全天提醒默认当地09:00。</p></>}{tab==='users'&&<UserManagement accountId={state.user.userId}/>} {tab==='account'&&<><div className="account-card"><span className="avatar">{state.user.displayName.slice(0,1)}</span><div><strong>{state.user.displayName}</strong><p>{state.user.email}</p></div></div><p>{state.user.mode==='local'?'本地单人模式，数据保存在此服务的本地目录。无需账号密码。':'账号模式，使用此部署实例的青单账号登录，服务器数据按账号隔离。'}任务、习惯及专注记录每20秒同步；发生冲突时会提示核对。</p><p className="form-help">断网时可以保留当前输入，不能提交云端修改。创建与字段更新的未确认操作会保存到此浏览器，可手动同步核对。已加载数据可保存账号离线副本；完成/撤销/跳过、评论、习惯增量等指定操作可持久核对。完整后台自动同步、全部操作队列尚待补。独立离线壳可在此设备主动安装，真实浏览器安装/更新仍须验收。</p><label><input type="checkbox" checked={prefs.offlineCacheEnabled!==false} onChange={e=>setPref({offlineCacheEnabled:e.target.checked})}/>保存本账号已加载数据的离线副本</label><button className="subtle-button" onClick={async()=>{await invalidateOfflineSession('cache-cleared',state.user.userId);const ok=await new WorkspaceCache(state.user.userId,browserCacheBackend()).clear();actions.notify(ok?'此账号的离线副本已清除；若仍启用该设置，下次在线同步会重新保存。':'未能清除副本，请检查浏览器存储设置')}}>清除此账号离线副本</button><p className="form-help">只缓存上次已授权读取的数据，不缓存附件字节；离线时无法获知共享权限变化，联网后由服务器重新核对。公共电脑可以关闭此功能清除副本。</p><p className="form-help">未提交输入可能保存在此浏览器；不同账号使用独立命名空间。公共电脑请先导出待确认输入，再清除本账号草稿。</p><button className="subtle-button danger" onClick={()=>{if(confirm('清除此浏览器中本账号的全部未提交草稿和待确认操作？不会删除云端任务。请先导出必要输入；清除后将刷新页面。')){draftStore.clearAccount(state.user.userId);location.reload()}}}>清除本账号本地草稿</button><OfflineShellSettings accountId={state.user.userId}/><button className="subtle-button" onClick={actions.refresh}><RefreshCw size={15}/>立即同步</button>{state.user.mode!=='local'&&<a className="subtle-button danger" href="/api/auth/logout" target="_top" onClick={async e=>{e.preventDefault();try{await invalidateOfflineSession('signout-requested',state.user.userId);await api('/api/auth/logout',{});location.assign('/')}catch(error){setError('退出登录尚未确认。'+(error as Error).message)}}}><LogOut size={15}/>退出登录</a>}</>}{tab==='notifications'&&<><h3>专注计时</h3><label>番茄时长（分钟）<input type="number" min={1} max={180} aria-label="番茄时长" value={prefs.focusMinutes} onChange={e=>preferencesForm.change({focusMinutes:e.target.value}as unknown as RecordData)} onBlur={()=>preferencesForm.saveField('focusMinutes')}/></label><label>休息时长（分钟）<input type="number" min={1} max={60} aria-label="休息时长" value={prefs.breakMinutes} onChange={e=>preferencesForm.change({breakMinutes:e.target.value}as unknown as RecordData)} onBlur={()=>preferencesForm.saveField('breakMinutes')}/></label><label>长休息（分钟，每4个番茄）<input type="number" min={1} max={60} aria-label="长休息时长" value={prefs.longBreakMinutes} onChange={e=>preferencesForm.change({longBreakMinutes:e.target.value}as unknown as RecordData)} onBlur={()=>preferencesForm.saveField('longBreakMinutes')}/></label><label>每日专注目标（分钟）<input type="number" min={1} max={1440} aria-label="每日专注目标" value={prefs.focusGoalMinutes} onChange={e=>preferencesForm.change({focusGoalMinutes:e.target.value}as unknown as RecordData)} onBlur={()=>preferencesForm.saveField('focusGoalMinutes')}/></label><label><input type="checkbox" checked={!!prefs.autoStages} onChange={e=>setPref({autoStages:e.target.checked})}/>自动在专注和休息之间切换</label><p className="form-help">自动阶段仅在打开的应用中运行，每4个已完成番茄安排长休息。关闭应用不自动创建新的计时。</p><h3>浏览器提醒</h3><p>提醒仅在应用页面打开时检查。关闭页面后，没有后台推送、邮件或系统闹钟保证。计时器重新打开时会按云端时间恢复。</p><button className="primary" onClick={async()=>{if(!('Notification' in window)){setError('当前浏览器不支持通知。');return;}const p=await Notification.requestPermission();actions.notify(p==='granted'?'浏览器通知已允许':'浏览器未允许通知')}}>允许浏览器通知</button></>}{tab==='data'&&<><h3>轻量记录备份（v1）</h3><p>JSON 包含我的任务、清单、习惯、专注记录和历史摘要；完整撤销快照保留在云端。共享清单的数据不会冒充为我的备份。附件仅导出清单和下载链接，文件内容需单独下载。</p><label>所选文件格式<select aria-label="主动选择任务文件导入格式" value={importFormat} disabled={importing} onChange={e=>setImportFormat(e.target.value)}><option value="auto">青单v1 / 通用CSV / Todoist CSV / ICS</option><option value="graph-todo">Microsoft Graph To Do任务JSON快照（手动文件）</option></select></label>{importFormat==='graph-todo'&&<p className="form-help">按官方todoTask JSON结构处理；可解析UTC/IANA时区，不连接微软，不支持PST/原生整包；未知时区/字段及重复/提醒保留原文，附件字节不恢复。选完整任务集，含下一页标记会停止。</p>}<div className="button-row"><button className="primary" onClick={exportBackup}><Download size={15}/>导出 JSON</button><button className="subtle-button" onClick={exportCSV}><Download size={15}/>导出 CSV</button><button className="subtle-button" disabled={importing} onClick={()=>importRef.current?.click()}><Upload size={15}/>{importing?'正在导入…':importFormat==='graph-todo'?'导入 Graph任务JSON':'导入 JSON / CSV / ICS'}</button></div><input type="file" accept="application/json,.json,.csv,.ics" hidden ref={importRef} onChange={e=>{if(e.target.files?.[0])importFile(e.target.files[0]);e.target.value=''}}/><FullBackupPanel userId={state.user.userId} onRefresh={actions.refresh}/><ListTransferRecovery state={state} onRefresh={actions.refresh}/><h3>日历文件</h3><p>导出当前有日期任务的 ICS 快照。该文件不包含持续订阅或双向同步。定时任务带时区；保留导入的明确UTC时刻，修改日期后重新按当前时区解释。</p><button className="subtle-button" onClick={exportICS}><CalendarDays size={15}/>导出 ICS</button><p className="form-help">可导入通用任务CSV、Todoist CSV和ICS快照，不支持的字段会明确提示。MS To Do专有格式、Google/CalDAV双向同步未连接。</p></>}{tab==='shortcuts'&&<><h3>更快地安排任务</h3><div className="shortcut"><span>添加任务</span><kbd>N</kbd></div><div className="shortcut"><span>搜索</span><kbd>/</kbd></div><div className="shortcut"><span>打开搜索</span><kbd>⌘ / Ctrl + K</kbd></div><div className="shortcut"><span>撤销最近修改</span><kbd>⌘ / Ctrl + Z</kbd></div><div className="shortcut"><span>关闭弹窗或详情</span><kbd>Esc</kbd></div><div className="shortcut"><span>批量添加，换行</span><kbd>Shift + Enter</kbd></div><p className="form-help">输入法候选确认不会提交任务。浏览器内快捷键不等同于系统全局快捷键。</p></>}{tab==='about'&&<><div className="brand-logo">✓</div><h3>青单</h3><p>已提供：云端任务与多级子任务、清单与分组、标签、优先级、日期与重复、评论与附件、日历/看板/四象限、番茄/正计时、习惯、统计、备份与恢复。</p><p>尚未覆盖：未公布年份调休资料、关闭页面后台提醒、已认证会话完整离线应用壳及后台自动同步、原生系统集成、复杂HTML编辑、真实第三方日历双向同步、AI语音和外部MCP配置。</p><p className="form-help">页面中的功能直接操作同一份云端记录。没有用于展示的假同步或虚构集成。</p></>}{preferencesForm.controls}{error&&<div className="inline-error">{error}</div>}</section></div></Modal>;
}
